mapper.select:
SELECT id, user_id, title, database_type, created_at, updated_at
FROM chat_conversation
WHERE id = #{id} AND user_id = #{userId}

SELECT id, conversation_id, role, content, sql_text, query_plan_json,
       response_json, created_at
FROM (
    SELECT id, conversation_id, role, content, sql_text, query_plan_json,
           response_json, created_at
    FROM chat_message
    WHERE conversation_id = #{conversationId}

        AND id < #{beforeMessageId}

    ORDER BY id DESC
    LIMIT #{limit}
) recent
ORDER BY id ASC
